head.b:skin:
:root {
  --bg: #0f172a;
  --card: #111827;
  --panel: #1f2937;
  --text: #e5e7eb;
  --muted: #94a3b8;
  --accent: #60a5fa;
  --accent-2: #22d3ee;
  --border: rgba(148,163,184,0.2);
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
  line-height: 1.7;
}

* { box-sizing: border-box; }
a { color: var(--accent); text-decoration: none; }
a:hover { color: var(--accent-2); }

.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 20px;
}

.header {
  background: rgba(15,23,42,0.95);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 20;
  backdrop-filter: blur(8px);
}

.header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 72px;
}

.brand {
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.nav {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
  font-size: 0.92rem;
}

.main-wrapper {
  padding: 36px 0 60px;
}

.blog-posts {
  display: grid;
  gap: 28px;
}

.post {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 28px;
}

.post h2 {
  margin: 0 0 8px;
  font-size: clamp(1.5rem,2vw,2rem);
}

.post .post-header {
  color: var(--muted);
  font-size: 0.82rem;
  margin-bottom: 12px;
}

.post .post-body {
  color: var(--text);
}

.post .post-body p {
  margin: 0 0 16px;
}

.footer {
  border-top: 1px solid var(--border);
  padding: 20px 0 40px;
  text-align: center;
  color: var(--muted);
}

@media (max-width: 768px) {
  .header .container {
    flex-direction: column;
    justify-content: center;
    padding: 16px 20px;
  }

  .nav {
    justify-content: center;
  }

  .post {
    padding: 22px 18px;
  }
}
